<?php if ( ! defined('BASEPATH')) exit('No direct script access allowed');class Followup_model extends CI_Model{			public function followup_detail(){		$this->db->select('company.name,branch.city,enquiry.*');		$this->db->join('company','company.company_id = enquiry.company');	$this->db->join('branch','branch.branch_id = enquiry.branch');	$this->db->where('enquiry.id',$this->uri->segment(1));	$this->db->order_by('enquiry.id','DESC');	$result = $this->db->get('enquiry');	return $result->row();	}		public function new_followup(){            	$data = array(	'enquiry_id'			=>$this->uri->segment(1),	'followup_status'		=>$this->security->xss_clean($this->input->post('followup_status')),	'followup_date'			=>$this->security->xss_clean($this->input->post('followup_date')),	'followup_remarks'		=>ucwords(strtolower($this->security->xss_clean($this->input->post('followup_remarks')))),	'date'				=>date('Y-m-d')		);			$result = $this->db->insert('followups',$data);	$update = array(	'status'	   =>$this->security->xss_clean($this->input->post('followup_status'))	);	$this->db->where('id',$this->uri->segment(1));	$this->db->update('enquiry',$update);			if($this->security->xss_clean($this->input->post('followup_status')) == 'Send Quotation Now'){            $this->db->select('id');            $this->db->order_by('id','DESC');            $this->db->limit(1);            $id = $this->db->get('quotation');            $id = $id->row();	if(!empty($id)){            $no = $id->id + 1;		}else{            $no = 1;	}        $this->db->select('company');        $this->db->where('id',$this->uri->segment(1));        $company_id = $this->db->get('enquiry');        $company_id = $company_id->row();        $company_id = $company_id->company;	$this->db->where('enquiry.company',$company_id);	$this->db->join('quotation','quotation.enquiry_id = enquiry.id');	$query = $this->db->get('enquiry');	$num_rows = $query->num_rows();	$old_quotation_no =$query->row();		if($num_rows > 0){	$quotation_no = $old_quotation_no->quotation_number.'-0'.$num_rows;	}else{    $this->db->select('admin.name');    $this->db->join('admin','admin.id = enquiry.added_by');	$this->db->where('enquiry.id',$this->uri->segment(1));	$added_by = $this->db->get('enquiry');	$added_by = $added_by->row();	    $rf =  implode('', array_map(function($v) { return $v[0]; }, explode(' ', $added_by->name)));			$quotation_no = 'IT/QT/'.$rf.'/21-22/'.$no;	if( $this->security->xss_clean($this->input->post('mode')) == "Indiamart" ){	$quotation_no = "IT/QT/IM/21-22/".$no;    	}		}		$quotation_data = array(	'enquiry_id'		=>$this->uri->segment(1),	'quotation_number'	=>$quotation_no,	'quotation_status'	=>0,	'remark'			=>$this->security->xss_clean($this->input->post('followup_remarks')),	'date'              =>date('Y-m-d h:i:s')	);	$result = $this->db->insert('quotation',$quotation_data);	$quotation_id = $this->db->insert_id();	redirect($quotation_id.'/print-quotation');	}			if($result){	return true;	}else{		return false;	}		}		public function all_followup(){			$this->db->where('enquiry_id',$this->uri->segment(1));	$this->db->order_by('id','DESC');		$result = $this->db->get('followups');		return $result->result();	}		public function quotation_detail(){		$this->db->select('company.name,branch.country,branch.state,branch.city,branch.address,branch.contact_person,branch.contact_number,branch.email,enquiry.mode,enquiry.enquiry_for,quotation.*');		$this->db->join('enquiry','enquiry.id = quotation.enquiry_id');	$this->db->join('company','company.company_id = enquiry.company');	$this->db->join('branch','branch.branch_id = enquiry.branch');	$this->db->where('quotation.id',$this->uri->segment(1));	$result = $this->db->get('quotation');	return $result->row(); 		}		public function new_quotation_followup(){			$data = array(	'quotation_id' =>$this->uri->segment(1),	'close_status' =>$this->security->xss_clean($this->input->post('close_status')),	'status'	   =>$this->security->xss_clean($this->input->post('followup_status')),	'remarks'	   =>$this->security->xss_clean(ucwords(strtolower($this->input->post('followup_remarks')))),	'date'         =>date('Y-m-d h:i:s')	);			$result = $this->db->insert('quotation_followup',$data);		    $update = array(	'quotation_status'=>$this->security->xss_clean($this->input->post('followup_status')),	'remark'=>$this->security->xss_clean(ucwords(strtolower($this->input->post('followup_remarks'))))    );	$this->db->where('id',$this->uri->segment(1));	$this->db->update('quotation',$update);		if($this->input->post('close_status') == 'Award To Us'){		$project = array(	'quotation_id' =>$this->uri->segment(1),	'remarks'	   =>$this->security->xss_clean(ucwords(strtolower($this->input->post('followup_remarks')))),	'status'	   =>1,	'date'         =>date('Y-m-d h:i:s')	);	$result = $this->db->insert('project_awarded',$project);		}else{		$this->db->set('status',0);	$this->db->where('quotation_id',$this->uri->segment(1));		$this->db->update('project_awarded');		}		if($result){	return true;	}else{		return false;	}		}		public function quotation_followups(){			$this->db->where('quotation_id',$this->uri->segment(1));	$result = $this->db->get('quotation_followup');	return $result->result();		}		public function tender_detail(){		$this->db->select('company.name,company.company_id,branch.city,branch.branch_id,tender.*');		$this->db->join('company','company.company_id = tender.company_id');	$this->db->join('branch','branch.branch_id = tender.branch_id');	$this->db->where('tender.id',$this->uri->segment(1));	$this->db->where('tender.is_deleted',0);	$result = $this->db->get('tender');	return $result->row();		}			public function new_tender_followup(){			$data = array(	'tender_id'    	  =>$this->uri->segment(1),	'followup_status' =>$this->security->xss_clean($this->input->post('status')),	'followup_date'	  =>$this->security->xss_clean($this->input->post('followup_date')),	'remarks'	   	  =>$this->security->xss_clean(ucwords(strtolower($this->input->post('remarks')))),	'date'            =>date('Y-m-d h:i:s')	);			$result = $this->db->insert('tender_followup',$data);			$update = array(	'status'	=>$this->security->xss_clean($this->input->post('status')),	'remarks'	=>$this->security->xss_clean(ucwords(strtolower($this->input->post('remarks'))))	);	$this->db->where('id',$this->uri->segment(1));	$this->db->update('tender',$update);			if($this->security->xss_clean($this->input->post('status')) == 1){		$bid_data = array(	'tender_id'			=>$this->uri->segment(1),	'bid_number	'		=>$this->security->xss_clean($this->input->post('bid_no')),	'status'			=>'',	'company_id'		=>$this->security->xss_clean($this->input->post('company')),	'branch_id'			=>$this->security->xss_clean($this->input->post('branch')),	'remarks'           =>$this->security->xss_clean(ucwords(strtolower($this->input->post('remarks')))),	'date'              =>date('Y-m-d')	);	$bid_insert = $this->db->insert('bid',$bid_data);	}		if($result){	return true;	}else{		return false;	}		}		public function tender_followups(){			$this->db->where('tender_id',$this->uri->segment(1));	$this->db->where('is_deleted',0);	$this->db->order_by('id','DESC');		$result = $this->db->get('tender_followup');	$result = $result->result();	return $result;	}		public function bid_detail(){            $this->db->select('tender.equipment,tender.tender_for,tender.e_tender_id,tender.remarks,company.name,branch.city,bid.*');	            $this->db->join('tender','tender.id = bid.tender_id');            $this->db->join('company','company.company_id = tender.company_id');            $this->db->join('branch','branch.branch_id = tender.branch_id');            $this->db->where('bid.id',$this->uri->segment(1));            $this->db->where('bid.is_deleted',0);            $result = $this->db->get('bid');            return $result->row();        }		public function new_bid_followup(){			$data = array(	'bid_id'    	  =>$this->uri->segment(1),	'followup_status' =>$this->security->xss_clean($this->input->post('status')),	'awarded_company' =>$this->security->xss_clean($this->input->post('awarded_company')),	'remarks'	   	  =>$this->security->xss_clean(ucwords(strtolower($this->input->post('remarks')))),	'date'            =>date('Y-m-d h:i:s')	);			$result = $this->db->insert('bid_followup',$data);			$this->db->set('status',$this->security->xss_clean($this->input->post('status')));	$this->db->where('id',$this->uri->segment(1));	$this->db->update('bid');		if($this->input->post('status') == 'Awarded to Us'){            $project = array('bid_id' =>$this->uri->segment(1),                            'remarks' =>$this->security->xss_clean(ucwords(strtolower($this->input->post('followup_remarks')))),                            'status'  =>1);            $result = $this->db->insert('project_awarded',$project);	}/*else{                $this->db->set('status',0);                $this->db->where('quotation_id',$this->uri->segment(1));	                $this->db->update('project_awarded');	            }	*/	if($result){            return true;	}else{            return false;	}    }    public function bid_followups(){        $this->db->where('bid_id',$this->uri->segment(1));        $this->db->where('is_deleted',0);        $this->db->order_by('id','DESC');        $result = $this->db->get('bid_followup');        $result = $result->result();        return $result;    }			public function multiple_enquiry($id){	$this->db->where('enquiry_id',$id);	$result = $this->db->get('multiple_enquiry');	$result = $result->result();	return $result;	    	}		}?>